18	/// A reference to a type in the input schema. It should mostly be the
19	/// reference to a concrete entity type, either one declared with `@entity`
20	/// in the input schema, or the object type that stores aggregations for a
21	/// certain interval, in other words a type that is actually backed by a
22	/// database table. However, it can also be a reference to an interface type
23	/// for historical reasons.
24	///
25	/// Even though it is not implemented as a string type, it behaves as if it
26	/// were the string name of the type for all external purposes like
27	/// comparison, ordering, and serialization
28	#[derive(Clone, CheapClone)]
29	pub struct EntityType {
30	    schema: InputSchema,
31	    pub(in crate::schema) atom: Atom,
32	}
33	
34	impl EntityType {
35	    pub(in crate::schema) fn new(schema: InputSchema, atom: Atom) -> Self {
36	        EntityType { schema, atom }
37	    }
38	
39	    /// Return the name of this type as a string.
40	    pub fn as_str(&self) -> &str {
41	        // unwrap: we constructed the entity type from the schema's pool
42	        self.schema.pool().get(self.atom).unwrap()
43	    }
44	
45	    /// Return the name of the declared type from the input schema that this
46	    /// type belongs to. For object and interface types, that's the same as
47	    /// `as_str()`, but for aggregations it's the name of the aggregation
48	    /// rather than the name of the specific aggregation for an interval. In
49	    /// that case, `as_str()` might return `Stats_hour` whereas `typename()`
50	    /// returns `Stats`
51	    pub fn typename(&self) -> &str {
52	        self.schema.typename(self.atom)
53	    }
54	
55	    pub fn is_poi(&self) -> bool {
56	        self.as_str() == POI_OBJECT
57	    }
58	
59	    pub fn has_field(&self, field: Atom) -> bool {
60	        self.schema.has_field(self.atom, field)
61	    }
62	
63	    pub fn field(&self, name: &str) -> Option<&Field> {
64	        self.schema.field(self.atom, name)
65	    }
66	
67	    pub fn is_immutable(&self) -> bool {
68	        self.schema.is_immutable(self.atom)
69	    }
70	
71	    pub fn id_type(&self) -> Result<IdType, Error> {
72	        self.schema.id_type(self.atom)
73	    }
74	
75	    /// Return the object type for this entity type. It is an error to call
76	    /// this if `entity_type` refers to an interface or an aggregation as
77	    /// they don't have an underlying type that stores daa directly
78	    pub fn object_type(&self) -> Result<&ObjectType, Error> {
79	        self.schema.object_type(self.atom)
80	    }
81	
82	    /// Create a key from this type for an onchain entity
83	    pub fn key(&self, id: Id) -> EntityKey {
84	        self.key_in(id, CausalityRegion::ONCHAIN)
85	    }
86	
87	    /// Create a key from this type for an entity in the given causality region
88	    pub fn key_in(&self, id: Id, causality_region: CausalityRegion) -> EntityKey {
89	        EntityKey::new(self.cheap_clone(), id, causality_region)
90	    }
91	
92	    /// Construct an `Id` from the given string and parse it into the
93	    /// correct type if necessary
94	    pub fn parse_id(&self, id: impl Into<Word>) -> Result<Id, Error> {
95	        let id = id.into();
96	        let id_type = self
97	            .schema
98	            .id_type(self.atom)
99	            .with_context(|| format!("error determining id_type for {}[{}]", self.as_str(), id))?;
100	        id_type.parse(id)
101	    }
102	
103	    /// Construct an `IdList` from a list of given strings and parse them
104	    /// into the correct type if necessary
105	    pub fn parse_ids(&self, ids: Vec<impl Into<Word>>) -> Result<IdList, Error> {
106	        let ids: Vec<_> = ids
107	            .into_iter()
108	            .map(|id| self.parse_id(id))
109	            .collect::<Result<_, _>>()?;
110	        IdList::try_from_iter(self.id_type()?, ids.into_iter())
111	            .map_err(|e| anyhow::anyhow!("error: {}", e))
112	    }
113	
114	    /// Parse the given `id` into an `Id` and construct a key for an onchain
115	    /// entity from it
116	    pub fn parse_key(&self, id: impl Into<Word>) -> Result<EntityKey, Error> {
117	        let id_value = self.parse_id(id)?;
118	        Ok(self.key(id_value))
119	    }
120	
121	    /// Parse the given `id` into an `Id` and construct a key for an entity
122	    /// in the give causality region from it
123	    pub fn parse_key_in(
124	        &self,
125	        id: impl Into<Word>,
126	        causality_region: CausalityRegion,
127	    ) -> Result<EntityKey, Error> {
128	        let id_value = self.parse_id(id.into())?;
129	        Ok(self.key_in(id_value, causality_region))
130	    }
131	
132	    fn same_pool(&self, other: &EntityType) -> bool {
133	        Arc::ptr_eq(self.schema.pool(), other.schema.pool())
134	    }
135	
136	    pub fn interfaces(&self) -> impl Iterator<Item = &InterfaceType> {
137	        self.schema.interfaces(self.atom)
138	    }
139	
140	    /// Return a list of all entity types that implement one of the
141	    /// interfaces that `self` implements; the result does not include
142	    /// `self`
143	    pub fn share_interfaces(&self) -> Result<Vec<EntityType>, Error> {
144	        self.schema.share_interfaces(self.atom)
145	    }
146	
147	    /// Return `true` if `self` is an object type, i.e., a type that is
148	    /// declared with an `@entity` directive in the input schema. This
149	    /// specifically excludes interfaces and aggregations.
150	    pub fn is_object_type(&self) -> bool {
151	        self.schema.is_object_type(self.atom)
152	    }
153	
154	    /// Whether the table for this entity type uses a sequence for the `vid` or whether
155	    /// `graph-node` sets them explicitly. See  also [`InputSchema.strict_vid_order()`]
156	    pub fn has_vid_seq(&self) -> bool {
157	        // Currently the agregations entities don't have VIDs in insertion order
158	        self.schema.strict_vid_order() && self.is_object_type()
159	    }
160	}
161	
162	impl fmt::Display for EntityType {
163	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
164	        write!(f, "{}", self.as_str())
165	    }
166	}
167	
168	impl Borrow<str> for EntityType {
169	    fn borrow(&self) -> &str {
170	        self.as_str()
171	    }
172	}
173	
174	impl std::fmt::Debug for EntityType {
175	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
176	        write!(f, "EntityType({})", self.as_str())
177	    }
178	}
179	
180	impl PartialEq for EntityType {
181	    fn eq(&self, other: &Self) -> bool {
182	        if self.same_pool(other) && self.atom == other.atom {
183	            return true;
184	        }
185	        self.as_str() == other.as_str()
186	    }
187	}
188	
189	impl Eq for EntityType {}
190	
191	impl PartialOrd for EntityType {
192	    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
193	        Some(self.cmp(other))
194	    }
195	}
196	
197	impl Ord for EntityType {
198	    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
199	        self.as_str().cmp(other.as_str())
200	    }
201	}
202	
203	impl std::hash::Hash for EntityType {
204	    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
205	        self.as_str().hash(state)
206	    }
207	}
