209	/// A trait to mark types that can reasonably turned into the name of an
210	/// entity type
211	pub trait AsEntityTypeName {
212	    fn name(&self) -> &str;
213	}
214	
215	impl AsEntityTypeName for &str {
216	    fn name(&self) -> &str {
217	        self
218	    }
219	}
